'use strict';
const WORFeed=(()=>{
 const catalog=window.WOR_FEED_VIDEOS||[];
 let expanded=false;
 const positions=['Haut · gauche','Haut · centre','Haut · droite','Milieu · gauche','Milieu · centre','Milieu · droite','Bas · gauche','Bas · centre','Bas · droite'];
 function shuffled(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
 function settings(){const l=WORLab.getLab();if(!l.feed)l.feed={position:4,order:shuffled(catalog.map(v=>v.id)),device:'desktop',reveal:false};const f=l.feed;
  if(!l.candidates.some(c=>c.id===f.candidateId))f.candidateId=l.candidates[0]?.id||null;
  if(!Number.isInteger(f.position)||f.position<0||f.position>8)f.position=4;
  f.order=[...new Set([...(Array.isArray(f.order)?f.order:[]),...catalog.map(v=>v.id)])].filter(id=>catalog.some(v=>v.id===id));
  return f;
 }
 const candidate=()=>WORLab.getLab().candidates.find(c=>c.id===settings().candidateId);
 function cards(){const f=settings(),c=candidate(),neighbors=f.order.slice(0,8).map(id=>catalog.find(v=>v.id===id));const rows=[...neighbors];rows.splice(f.position,0,c?{id:c.id,title:WORLab.title(c)||'Titre à renseigner dans le prétest',channel:'Words of Rizdom',image:c.image,own:true}:{id:'empty',title:'Ta miniature apparaîtra ici',channel:'Words of Rizdom',own:true});return rows}
 function card(v,i){return `<article class="yt-card ${v.own&&settings().reveal?'yt-revealed':''}" data-feed-slot="${i}" ${v.own?'data-feed-own="true"':''}><div class="yt-thumb">${v.image?`<img src="${esc(v.image)}" alt="${esc(v.title)}" decoding="async">`:'<span class="yt-placeholder">Importe une miniature pour commencer</span>'}${v.own&&settings().reveal?'<span class="yt-marker">Ta miniature</span>':''}</div><div class="yt-info"><span class="yt-avatar" aria-hidden="true">${esc(v.channel.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><h3>${esc(v.title)}</h3><p>${esc(v.channel)}</p></div><span class="yt-dots" aria-hidden="true">⋮</span></div></article>`}
 function grid(){return cards().map(card).join('')}
 function renderFeed(){const l=WORLab.getLab(),f=settings(),c=candidate();document.body.classList.toggle('feed-focus',expanded);
  return head('LA MISE EN SITUATION','Est-ce qu’elle sort du lot ?','Change une seule miniature. Garde le même environnement. Compare ton premier regard.')+episodeLine()+WORPretest.tabs('youtube')+`
  <section class="feed-controls panel" aria-label="Commandes de l’aperçu YouTube">
   <div class="feed-controls-top"><div><span class="meta-caps">DANS YOUTUBE</span><h2>Ton image parmi les autres.</h2></div><button class="button small" id="feed-expand" aria-pressed="${expanded}">${expanded?'↙ Réduire':'↗ Agrandir la grille'}</button></div>
   <div class="feed-fields"><label class="field feed-choice">Miniature affichée<select id="feed-candidate" aria-label="Miniature affichée" ${c?'':'disabled'}>${l.candidates.map(x=>`<option value="${esc(x.id)}" ${x.id===c?.id?'selected':''}>${esc(x.variantLabel)} · ${esc(x.name)}</option>`).join('')||'<option>Aucune miniature importée</option>'}</select></label><div class="feed-arrows"><button class="button" id="feed-prev" aria-label="Miniature précédente" ${l.candidates.length<2?'disabled':''}>←</button><button class="button" id="feed-next" aria-label="Miniature suivante" ${l.candidates.length<2?'disabled':''}>→</button></div><label class="field feed-position">Position<select id="feed-position" aria-label="Position">${positions.map((p,i)=>`<option value="${i}" ${f.position===i?'selected':''}>${i+1} · ${f.device==='mobile'?'Dans le fil mobile':p}</option>`).join('')}</select></label><div class="feed-device" role="group" aria-label="Format de l’aperçu"><button class="button ${f.device==='mobile'?'':'primary'}" id="feed-desktop" aria-pressed="${f.device!=='mobile'}">Ordinateur</button><button class="button ${f.device==='mobile'?'primary':''}" id="feed-mobile" aria-pressed="${f.device==='mobile'}">Mobile</button></div></div>
   ${l.candidates.length?`<div class="feed-variants" aria-label="Tes variantes">${l.candidates.map(x=>`<button class="feed-variant ${x.id===c?.id?'active':''}" data-feed-variant="${esc(x.id)}" aria-label="Afficher la variante ${esc(x.variantLabel)}" aria-pressed="${x.id===c?.id}"><img src="${esc(x.image)}" alt=""><span>${esc(x.variantLabel)}</span></button>`).join('')}</div>`:'<p>Commence par ajouter tes images dans le prétest.</p><button class="button primary" id="feed-import">Importer mes miniatures →</button>'}
   <div class="feed-options"><div><button class="button small" id="feed-shuffle">↻ Mélanger les vidéos voisines</button><button class="button small" id="feed-random">Déplacer au hasard</button></div><label><input id="feed-reveal" type="checkbox" ${f.reveal?'checked':''}> Repérer ma miniature</label><label><input id="feed-images-only" type="checkbox" ${f.imagesOnly?'checked':''}> Images seules</label></div>
   <p class="feed-status" id="feed-status" role="status">${status()}</p>
  </section>
  <section class="feed-stage ${f.device==='mobile'?'is-mobile':''} ${f.imagesOnly?'images-only':''}" id="feed-stage" aria-label="Simulation de page d’accueil YouTube">
   <div class="yt-header"><span class="yt-menu" aria-hidden="true">☰</span><div class="yt-logo"><span aria-hidden="true">▶</span> YouTube</div><div class="yt-search" aria-hidden="true">Rechercher<span>⌕</span></div><span class="yt-profile" aria-hidden="true">N</span></div>
   <div class="yt-topics" aria-hidden="true"><span>Tout</span><span>Trading</span><span>Prop firms</span><span>Podcasts</span><span>Stratégies</span><span>Marchés financiers</span></div>
   <div class="yt-grid" id="feed-grid">${grid()}</div>
  </section>
  <p class="feed-note">Reconstitution locale pour comparer visuellement · aucune mesure de clics ni prédiction de performance. Les miniatures importées conservent leur grain ; cet aperçu ne les modifie pas.</p>
  <details class="feed-sources"><summary>Les vidéos de référence · ${catalog.length} miniatures de trading</summary><p>Miniatures et titres publics récupérés le 13 octobre 2026. La grille est une sélection de références, pas ta page YouTube personnalisée. Aucune vue ni durée n’est inventée.</p><ul>${catalog.map(v=>`<li><a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">${esc(v.title)}</a> <span>· ${esc(v.channel)}</span></li>`).join('')}</ul></details>`;
 }
 function status(){const c=candidate();return c?`Variante ${c.variantLabel} · emplacement ${settings().position+1}/9 · les vidéos voisines restent fixes quand tu changes de variante.`:'Aucune miniature à comparer pour cet épisode.'}
 function paint(){const f=settings();$('#feed-grid').innerHTML=grid();$('#feed-status').textContent=status();$('#feed-candidate').value=f.candidateId||'';$('#feed-position').value=f.position;[...$('#feed-position').options].forEach((o,i)=>o.textContent=`${i+1} · ${f.device==='mobile'?'Dans le fil mobile':positions[i]}`);$$('[data-feed-variant]').forEach(b=>{const yes=b.dataset.feedVariant===f.candidateId;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',String(yes))});const stage=$('#feed-stage');stage.classList.toggle('is-mobile',f.device==='mobile');stage.classList.toggle('images-only',!!f.imagesOnly);['desktop','mobile'].forEach(d=>{const b=$('#feed-'+d),yes=f.device===d;b.classList.toggle('primary',yes);b.setAttribute('aria-pressed',String(yes))});persist()}
 function choose(id){if(!WORLab.getLab().candidates.some(c=>c.id===id))return;settings().candidateId=id;paint()}
 function step(delta){const rows=WORLab.getLab().candidates;if(rows.length<2)return;const i=rows.findIndex(c=>c.id===settings().candidateId);choose(rows[(i+delta+rows.length)%rows.length].id)}
 function open(id){if(id&&WORLab.getLab().candidates.some(c=>c.id===id))settings().candidateId=id;navigate('youtube');persist()}
 function wire(){WORPretest.wireTabs();on('feed-import',()=>navigate('ab'));on('feed-expand',()=>{expanded=!expanded;render();$('#feed-expand').focus()});on('feed-prev',()=>step(-1));on('feed-next',()=>step(1));$('#feed-candidate').onchange=e=>choose(e.target.value);$$('[data-feed-variant]').forEach(b=>b.onclick=()=>choose(b.dataset.feedVariant));$('#feed-position').onchange=e=>{settings().position=Number(e.target.value);paint()};on('feed-random',()=>{settings().position=(settings().position+1+Math.floor(Math.random()*8))%9;paint()});on('feed-shuffle',()=>{const f=settings(),old=f.order.join();f.order=shuffled(f.order);if(f.order.join()===old)f.order.push(f.order.shift());paint()});['desktop','mobile'].forEach(d=>on('feed-'+d,()=>{settings().device=d;paint()}));$('#feed-reveal').onchange=e=>{settings().reveal=e.target.checked;paint()};$('#feed-images-only').onchange=e=>{settings().imagesOnly=e.target.checked;paint()};}
 document.addEventListener('keydown',e=>{if(typeof view==='undefined'||view!=='youtube'||$('dialog[open]')||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement?.tagName)||document.activeElement?.isContentEditable)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();step(e.key==='ArrowRight'?1:-1)}});
 return {render:renderFeed,wire,open,settings,cards,shuffled};
})();
